using System;using System.Linq;
namespace IdleIntelligence.Core
{
 public static class MetaAutomation
 {
  public static double Fabrication(GameState s)=>(ItemSystemV3.Enabled(s)?1:PrestigeRules.F(s,"W08"))*(ItemSystemV3.Enabled(s)?1:Math.Pow(1/PrestigeRules.E("C06"),MetaRules.Level(s,"C06")));
  public static GameState Rebuild(GameState state){if(MetaRules.Level(state,"B04")==0||state.Meta.rebuild.Length==0)return state;var s=state;foreach(string id in state.Meta.rebuild){if(!state.Prestige.known.Contains(id)||PrestigeRules.Has(s,id))continue;var cost=ScientificNumber.From(PrestigeBalance.Nodes.First(n=>n.Id==id).Cost);if(s.Prestige.Free.CompareTo(cost.Add(ScientificNumber.FromData(s.Meta.intReserve)))<0)break;s=PrestigeRules.Buy(s,id);}return s;}
  public static ScientificNumber Protected(GameState s,bool research=false){var reserve=PrestigeAutomation.ProtectedData(s);if(!research&&PrestigeRules.Has(s,"F05")&&s.Prestige.director){var target=s.Prestige.researchTargets.FirstOrDefault(t=>Game.Level(s,t.id)<t.level);if(target!=null){int i=Game.ResearchIndex(target.id);if(Game.ResearchBlock(s,i)==null||Game.ResearchBlock(s,i)=="Zu wenig Daten"||Game.ResearchBlock(s,i)=="Labor belegt"){var cost=Game.ResearchCost(s,i);if(cost.CompareTo(reserve)>0)reserve=cost;}}}return reserve;}
  public static GameState Analysis(GameState s)=>!s.Prestige.resetIntent&&(MetaRules.Level(s,"C02")>0||PrestigeRules.Has(s,"F03"))&&s.Meta.analysisAuto&&s.Industry.analysisQueue.Length==0&&!s.Workshop.hasAnalysis&&s.Data.CompareTo(ScientificNumber.From(Industry.AnalysisCost(s,ItemBalance.Analyses[s.Meta.analysisRecipe].Cost)).Add(Protected(s)))>=0?MaterialAnalysis.Start(s,s.Meta.analysisRecipe):s;
  public static GameState Craft(GameState s)=>!s.Prestige.resetIntent&&MetaRules.Level(s,"C03")>0&&s.Meta.craftAuto&&s.Workshop.inventory.Count(i=>i.type==s.Meta.craftRecipe)<s.Meta.craftTarget&&s.Data.CompareTo(ScientificNumber.From(ItemBalance.Items[Workshop.Index(s.Meta.craftRecipe)].Data).Add(Protected(s)))>=0?Workshop.Craft(s,s.Meta.craftRecipe):s;
  public static GameState Fusion(GameState s){if(s.Prestige.resetIntent||MetaRules.Level(s,"C04")==0||!s.Meta.fusionAuto)return s;foreach(string type in s.Meta.fusionTypes)for(int rarity=0;rarity<s.Meta.fusionTarget;rarity++){var ids=s.Workshop.inventory.Where(i=>i.type==type&&i.rarity==rarity&&!Industry.Busy(s,i.id)&&!i.locked&&!i.challengeCopy&&!s.Workshop.equipped.Contains(i.id)).Take(3).Select(i=>i.id).ToArray();if(ids.Length==3){var next=Workshop.Fuse(s,ids);if(!ReferenceEquals(next,s))return next;}}return s;}
  public static GameState Salvage(GameState state,string id,double fragmentRoll)
  {var item=state.Workshop.inventory.FirstOrDefault(i=>i.id==id);if(item==null||Industry.Busy(state,id)||item.locked||item.challengeCopy||state.Workshop.equipped.Contains(id)||!ScientificNumber.Finite(fragmentRoll)||fragmentRoll<0||fragmentRoll>=1)return state;var s=state.Copy();double rate=Math.Min(MetaBalance.RecoveryCap,(MetaBalance.RecoveryBase+MetaBalance.RecoveryStep*MetaRules.Level(s,"C05"))*(1+ChallengeRules.Bonus(s,"closed-supply-chain")));for(int c=0;c<item.materialBasis.Length;c++){double value=Math.Max(0,item.materialBasis[c]-item.recoveryUsed[c])*rate+s.Meta.salvageRemainders[c];long n=(long)Math.Floor(value+1e-12);s.Workshop.components[c]+=n;Lifetime.Components(s,c,n);s.Meta.salvageRemainders[c]=Math.Max(0,value-n);}double chance=Math.Min(MetaBalance.SalvageCap,MetaBalance.SalvageChance[item.rarity]*(1+Workshop.Device(s,"fragment")));if(chance>0&&fragmentRoll<chance)s.Workshop.fragments++;s.Workshop.inventory=s.Workshop.inventory.Where(i=>i.id!=id).ToArray();s.Workshop.revision++;LocalJournal.Record(s,"item-salvage",permanent:false);return s;}
 }
}
